  log(`Starting nested Monte Carlo simulation...`);
  log(`Output files:`);
  log(`  Log: ${logFile}`);
  log(`  Results: ${resultsFile}`);

  try {
    const results = await runNestedMonteCarlo(args);

    // Write results to JSON file
    fs.writeFileSync(resultsFile, JSON.stringify(results, null, 2), 'utf8');

    log(`\n${'='.repeat(80)}`);
